package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BooleanUtils.toBoolean(String str)
 * Aiming for maximum branch and line coverage.
 */
public class BooleanUtils_toBoolean_TriageGen3Test {



    @Test
    public void testToBoolean_TrueCases() {
        // Test the identity optimization (interned string)
        assertTrue(BooleanUtils.toBoolean("true"));

        // Test case 4: lowercase 't' variations
        assertTrue(BooleanUtils.toBoolean("true"));
        assertTrue(BooleanUtils.toBoolean("trUE"));
        assertTrue(BooleanUtils.toBoolean("tRue"));
        assertTrue(BooleanUtils.toBoolean("trUe"));
        assertTrue(BooleanUtils.toBoolean("TrUe")); // This actually falls into the 't' block if 'T' is not matched exactly? 
        // Looking at code: if (ch == 't') handles 't' and if (ch == 'T') handles 'T'.
        // Let's test explicit branches:
        assertTrue(BooleanUtils.toBoolean("true"));
        assertTrue(BooleanUtils.toBoolean("tRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("trUE"));

        // Test case 4: uppercase 'T' variations
        assertTrue(BooleanUtils.toBoolean("TRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("tRUE"));
        assertTrue(BooleanUtils.toBoolean("tRuE")); // Wait, the logic is strict on the first char.

        // Re-evaluating implementation logic:
        // Case 4, ch == 't' branch:
        assertTrue(BooleanUtils.toBoolean("true"));
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("trUe"));
        assertTrue(BooleanUtils.toBoolean("tRUE"));

        // Case 4, ch == 'T' branch:
        assertTrue(BooleanUtils.toBoolean("TRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUe"));
        assertTrue(BooleanUtils.toBoolean("TRue"));
        assertTrue(BooleanUtils.toBoolean("T rUe")); // no, just char checks
        assertTrue(BooleanUtils.toBoolean("TRuE"));
    }








}

