package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BooleanUtils.toBoolean(String str)
 * Aiming for maximum branch and line coverage.
 */
public class BooleanUtils_toBoolean_TriageGen3Test {











    @Test
    public void testToBoolean_EdgeCases() {
        // Test non-interned "true"
        String nonInternedTrue = new String("true");
        // Note: The code uses `str == "true"`. 
        // In Java, `new String("true") == "true"` is FALSE.
        // However, the method is designed to fall through to the switch statement.
        // The switch statement for length 4 will catch "true" and return true.
        assertTrue(BooleanUtils.toBoolean(nonInternedTrue));

        // Test empty string
        assertFalse(BooleanUtils.toBoolean(""));

        // Test very long string
        assertFalse(BooleanUtils.toBoolean("truetruetrue"));

        // Test case 4 mismatches
        assertFalse(BooleanUtils.toBoolean("t r u e")); // length 7
        assertFalse(BooleanUtils.toBoolean("tru"));    // length 3
        assertFalse(BooleanUtils.toBoolean("true "));  // length 5
    }
}
